import json,os,pathlib,re,subprocess
t=pathlib.Path(os.environ['RUNNER_TEMP']);assert os.environ['GITHUB_RUN_ATTEMPT']=='1'
out=t/'top500-readback.private.json';assert not out.exists(),'ORIGINAL_TOP500_READ_OUTCOME_FIRST_NO_REPEAT'
sha=os.environ['EXPECTED_PRODUCTION_SHA'];assert re.fullmatch('[a-f0-9]{40}',sha)
intent=json.loads((t/'top500-input.private.json').read_text());assert intent['expected_installed_sha']==sha
ssh=['ssh','-i',str(t/'channel_key'),'-o','BatchMode=yes','-o','ConnectTimeout=10','-o','IdentitiesOnly=yes','-o','StrictHostKeyChecking=yes','-o','GlobalKnownHostsFile=/dev/null','-o','UserKnownHostsFile='+str(t/'channel_known_hosts'),os.environ['DEPLOY_USER']+'@'+os.environ['DEPLOY_HOST']]
remote="set -e; cd /var/www/anytoour/data/www/app.anytoour.ru; test \"$(git rev-parse HEAD)\" = '"+sha+"'; test -z \"$(git status --porcelain --untracked-files=no)\"; php"
with (t/'top500-metadata.php').open('rb') as src,out.open('wb') as dst:r=subprocess.run(ssh+[remote],stdin=src,stdout=dst,stderr=subprocess.PIPE,timeout=300)
d=json.loads(out.read_text().splitlines()[-1]);h=d.get('hotels',[])
s={k:d.get(k) for k in ['operation','ok','error','error_class','sqlstate','last_completed_stage','metadata_failure_is_not_absence','installed_sha','db_writes','gateway_calls','provider_post_reads','provider_channel_rights_checks','message_sends','photo_http']}
s.update(hotels=len(h),native_present=sum(x['current_native'] is not None for x in h),local_tv_present=sum(x['local_tv_metadata'] is not None for x in h),catalog_primary_image_hotels=sum(bool((x['current_native'] or {}).get('primary_image_url')) for x in h),local_tv_gallery_hotels=sum(bool((x['local_tv_metadata'] or {}).get('distinct_declared_image_url_count')) for x in h),stored_price_recent_hotels=sum(x['stored_price_last72h'] is not None for x in h),stored_price_recent_rows=sum((x['stored_price_last72h'] or {}).get('recent_rows',0) for x in h),policy_condition_rows=sum((x['stored_price_last72h'] or {}).get('existing_policy_condition_rows',0) for x in h),bound_native_ids=[x['native_hotel_id'] for x in h],rows=[{'native_id':x['native_hotel_id'],'native_present':x['current_native'] is not None,'has_catalog_primary':bool((x['current_native'] or {}).get('primary_image_url')),'local_tv_images':(x['local_tv_metadata'] or {}).get('distinct_declared_image_url_count'),'recent_price_rows':(x['stored_price_last72h'] or {}).get('recent_rows'),'policy_condition_rows':(x['stored_price_last72h'] or {}).get('existing_policy_condition_rows'),'price_metadata_state':x['stored_price_metadata_state'],'registry_match_count':sum(z['matches'] for z in x['registry_exact_native_metadata_matches'])} for x in h])
(t/'top500-summary.json').write_text(json.dumps(s)+'\n');print(json.dumps(s))
assert r.returncode==0 and d['ok'] and d['scope_native_ids']==intent['hotel_ids'] and len(h)==10
assert d['db_writes']==d['gateway_calls']==d['provider_post_reads']==d['message_sends']==d['photo_http']==0 and d['provider_channel_rights_checks']==2
